import re
def fmt(x):
    s=f"{x:.3f}".rstrip("0").rstrip("."); return s
def conv(v,unit):  # to years
    return fmt(float(v)/52) if unit=="w" else v
def parse_time(s):
    """return (bound, lo, hi, unit, notes) or None if not usable (notes only)"""
    raw=s; notes=[]
    if not s: return None
    if "<u>" in s: return ("amb",raw)
    if re.match(r"(Note|Lightly|Leaves|Resprouted|One plant|Unable)",s): return ("text",raw)
    m=re.fullmatch(r"At least (\d+) years",s)
    if m: return dict(b=">",lo=m.group(1),hi=None,u="y",n=[f"printed '{raw}'"])
    m=re.fullmatch(r"Less than (\d+) years?",s)
    if m: return dict(b="<",lo=m.group(1),hi=None,u="y",n=[f"printed '{raw}'"])
    t=s.replace("**","")
    # take first value if several comma-separated or space separated values
    first=re.split(r",\s*|\s+(?=c\.)",t)[0]
    if "**" in s or first!=t: notes.append(f"printed '{raw}'" + ("; bold = sizable proportion of population flowering" if "**" in s else ""))
    m=re.match(r"^(\?)?(c\.\s?)?(\?)?(\d+(?:\.\d+)?)(?:–(\d+(?:\.\d+)?))?(\+)?([wy])(.*)$",first)
    if not m:
        m2=re.match(r"^c\.(\d+)\.(\d+)y(.*)$",first)   # c.N.Ny = decimal
        if m2: m=None; lo=f"{m2.group(1)}.{m2.group(2)}"; return dict(b="",lo=lo,hi=None,u="y",n=notes+[f"printed '{raw}'"])
        return ("unparsed",raw)
    q1,c,q2,lo,hi,plus,u,rest=m.groups()
    if c: notes.append("printed with 'c.' (approximately)")
    if q1 or q2 or "?" in rest: notes.append("printed with '?' (uncertain)")
    b=""
    if plus: b=">"; notes.append(f"printed '{lo}+{u}', read as more than {lo}")
    rest=rest.strip("– ").strip()
    if rest:
        if not any(n.startswith("printed '") and raw in n for n in notes): notes.append(f"printed '{raw}'")
    return dict(b=b,lo=lo,hi=hi,u=u,n=notes,rest=rest)
def to_years(p):
    lo=conv(p["lo"],p["u"]); hi=conv(p["hi"],p["u"]) if p["hi"] else None
    v=p["b"]+lo+(f"-{hi}" if hi else "")
    return v
def raw_val(p):
    return p["b"]+p["lo"]+(f"-{p['hi']}" if p["hi"] else "")
